/** @type {import('tailwindcss').Config} */
// Material 3 (Material You) tokens. Colours resolve to the CSS variables generated by scripts/m3_theme.mjs (src/m3.css),
// as `rgb(var(--md-rgb-<role>) / <alpha-value>)` so opacity modifiers (bg-primary/10) keep working.
// docs/UX_BRIEF.md names (bg surface ink muted line low watch act info accent nodata) stay as aliases.
const c = (n) => `rgb(var(--md-rgb-${n}) / <alpha-value>)`

const ROLES = [
  'primary', 'on-primary', 'primary-container', 'on-primary-container',
  'secondary', 'on-secondary', 'secondary-container', 'on-secondary-container',
  'tertiary', 'on-tertiary', 'tertiary-container', 'on-tertiary-container',
  'error', 'on-error', 'error-container', 'on-error-container',
  'background', 'on-background',
  'surface', 'surface-dim', 'surface-bright',
  'surface-container-lowest', 'surface-container-low', 'surface-container', 'surface-container-high', 'surface-container-highest',
  'on-surface', 'surface-variant', 'on-surface-variant', 'outline', 'outline-variant',
  'inverse-surface', 'inverse-on-surface', 'inverse-primary', 'surface-tint', 'scrim',
  // semantic custom colours
  'on-low', 'low-container', 'on-low-container', 'low-fill', 'on-watch', 'watch-container', 'on-watch-container', 'watch-fill', 'act-fill',
]

export default {
  content: ['./index.html', './src/**/*.{ts,tsx}'],
  theme: {
    extend: {
      colors: {
        ...Object.fromEntries(ROLES.map((r) => [r, c(r)])),
        // ---- aliases (UX brief names) -> M3 roles
        bg: c('surface'),
        ink: c('on-surface'),
        muted: c('on-surface-variant'),
        line: c('outline-variant'),
        nodata: c('outline-variant'),
        low: { DEFAULT: c('low'), soft: c('low-container'), ink: c('on-low-container'), fill: c('low-fill') },
        watch: { DEFAULT: c('watch'), soft: c('watch-container'), ink: c('on-watch-container'), fill: c('watch-fill') },
        act: { DEFAULT: c('error'), soft: c('error-container'), ink: c('on-error-container'), fill: c('act-fill') },
        info: { DEFAULT: c('tertiary'), soft: c('tertiary-container'), ink: c('on-tertiary-container') },
        accent: { DEFAULT: c('primary'), soft: c('primary-container'), ink: c('on-primary-container') },
      },
      fontFamily: {
        sans: [
          'Roboto Flex', 'Noto Sans Devanagari', 'Noto Sans Telugu', 'Noto Sans Tamil', 'Noto Sans Bengali',
          'Noto Sans Kannada', 'Noto Sans Gujarati', 'Noto Sans Oriya', 'system-ui', '-apple-system', 'Segoe UI', 'Roboto', 'sans-serif',
        ],
      },
      // M3 shape scale: extra-small 4, small 8, medium 12, large 16, extra-large 28
      borderRadius: { 'm3-xs': '4px', 'm3-sm': '8px', 'm3-md': '12px', 'm3-lg': '16px', 'm3-xl': '28px' },
      boxShadow: {
        'elev-1': 'var(--md-sys-elevation-1)',
        'elev-2': 'var(--md-sys-elevation-2)',
        'elev-3': 'var(--md-sys-elevation-3)',
      },
    },
  },
  plugins: [],
}
